import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    strings = input_data[1:n+1]

    if n == 0:
        print(0)
        return

    def get_beauty(s):
        if not s:
            return 0
        max_run = 1
        current_run = 1
        for i in range(1, len(s)):
            if s[i] == s[i-1]:
                current_run += 1
            else:
                if current_run > max_run:
                    max_run = current_run
                current_run = 1
        if current_run > max_run:
            max_run = current_run
        return max_run

    def get_prefix_suffix(s):
        if not s:
            return 0, 0, ''
        first_char = s[0]
        last_char = s[-1]

        prefix_len = 0
        for c in s:
            if c == first_char:
                prefix_len += 1
            else:
                break

        suffix_len = 0
        for c in reversed(s):
            if c == last_char:
                suffix_len += 1
            else:
                break

        return prefix_len, suffix_len, first_char if first_char == last_char else ''

    def calc_max_internal(s):
        if not s:
            return 0
        res = 0
        cur = 1
        for i in range(1, len(s)): 
            if s[i] == s[i-1]:
                cur += 1
            else:
                if cur > res:
                    res = cur
                cur = 1
        if cur > res:
            res = cur
        return res

    total_beauty = 0
    if n >= 1:
        total_beauty = get_beauty(strings[0])
        p_len, s_len, char = get_prefix_suffix(strings[0])

