        if char and char == curr_char:
            bridge = s_len + curr_p
            if bridge > new_total_beauty:
                new_total_beauty = bridge

        total_beauty = new_total_beauty

        p_len_new = p_len
        s_len_new = s_len
        char_new = char

        if curr_char and char == curr_char:
            if curr_p == len(s_curr):
